function () {
            var _this = this;
            _super.prototype.execute.call(this);
            if (sgigame.RecoveryData.isRecovering) {
                TweenMax.delayedCall(1, function () {
                    _this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(server.ServerResponseEvent.LOGIC_RESPONSE));
                }, null, this);
                sgigame.RecoveryData.isRecovering = false;
                sgigame.HandleIncompleteGameCmd.IS_BASEGAME_RECOVERY = false;
                sgigame.HandleIncompleteGameCmd.IS_FEATURE_SELECTION_RECOVERY = false;
                sgigame.HandleIncompleteGameCmd.IS_FREESPIN_RECOVERY = false;
                sgigame.HandleIncompleteGameCmd.IS_LIL_RECOVERY = false;
                sgigame.RecoveryData.isLILRecovery = false;
                return;
            }
            var encoders = [
                this.getStakeEncode(),
                new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
            ];
            var history = this._historyModel.getNextState();
            if (history) {
                encoders.push(new sgigame.HistoryReplaceEncoder(history));
            }
            if (this._server.getLogicResponse() != undefined && this._server.getLogicResponse().reelSpinData[0] != undefined && this._server.getLogicResponse().reelSpinData[0].bonusAwarded) {
                var bonusChoiceEncoder;
                if (this._statesModel.getCurrentState().stateName == sgigame.BonusGameState.FREE_SPIN_INTRO) {
                    bonusChoiceEncoder = new sgigame.BonusChoiceEncoder(0);
                }
                else {
                    bonusChoiceEncoder = new sgigame.BonusChoiceEncoder(1);
                }
                encoders.push(bonusChoiceEncoder);
            }
            if (this._forceModel.forceSet) {
                var isBonus = false;
                if (this._statesModel.getSubGame() == sgigame.SubGames.BONUS_GAME && this._statesModel.getCurrentState().stateName != sgigame.BonusGameState.LIL_INTRO) {
                    isBonus = true;
                }
                else {
                    isBonus = false;
                }
                var heartMultipliers = (this._forceModel.reelData.heartMultipliers != undefined) ? this._forceModel.reelData.heartMultipliers : [];
                var goldenHeartTypes = (this._forceModel.reelData.goldenHeartTypes != undefined) ? this._forceModel.reelData.goldenHeartTypes : [];
                var forceEncoder = new sgigame.ForceEncoder(this._forceModel.reelData ? this._forceModel.reelData.positions : [-1, -1, -1, -1, -1], heartMultipliers, goldenHeartTypes, isBonus);
                encoders.push(forceEncoder);
            }
            this._forceModel.reset();
            this._forceModel.forceSet = false;
            if (this._statesModel.getCurrentState().stateName == sgigame.BaseGameStates.LOGIC_GLS_STATE) {
                this._data.startPlay();
            }
            var data = new server.GLSRequest(encoders);
            this._server.makeLogicRequest(data);
        }

