function (input, object) {
            if (input.getElementsByTagName("FSInfo") && input.getElementsByTagName("FSInfo").length > 0) {
                var node = input.getElementsByTagName("FSInfo")[0];
                var freeSpinInfoData = new sgigame.FreeSpinInfoData;
                freeSpinInfoData.totalFreeSpinWin = parseInt(this.getAttributeFromNode(node, "totalFreeSpinsWin", "number"));
