                freeSpinInfoData.remainingFreeSpins = parseInt(this.getAttributeFromNode(node, "remainingFreeSpins", "number"));
                freeSpinInfoData.currentFreeSpin = freeSpinInfoData.totalFreeSpins - freeSpinInfoData.remainingFreeSpins;
                freeSpinInfoData.triggerWin = parseInt(this.getAttributeFromNode(node, "scatterWin", "number"));
                freeSpinInfoData.wildMultiplier = parseInt(this.getAttributeFromNode(node, "wildSymbolMultiplier", "number"));
                object.freeSpinInfoData = freeSpinInfoData;
            }
        }

