                                    row = 2;
                                }
                                heartBeatAnim.x = ((i % 5) * 270) + ((i % 5) * 20);
                                heartBeatAnim.y = heartBeatAnim.y + sgigame.GameConfig.lilOnHandleCompPosY[sgigame.GameConfig.RESOLUTION_INDEX] + (row * 243) + (row * 5);
                                heartBeatAnim.visible = true;
                                heartBeatAnim.gotoAndPlay(0);
                                this._lilReelsView._heartBeatAnims[i] = heartBeatAnim;
                            }
