                    var heartSparkleSS = new components.SpriteSheet(sgigame.GameModels.assetCache.getAssetById(sgigame.BonusBundle.HeartSparkleJson.name), sgigame.GameModels.assetCache.getAssetById(sgigame.BonusBundle.HeartSparkleImg.name));
