                    for (var i = 0; i < reelSpinData.lockedReels.length; i++) {
                        this.updateMonetaryValuesInAllHearts(i, reelSpinData.heartAwardMultipliers[i] - 2);
                        var heartHighlight = new rendering.MovieClip(heartSparkleSS.getFrames());
                        heartHighlight.scaleX = heartHighlight.scaleY = 2;
                        heartHighlight.x = heartHighlight.x - 95;
                        heartHighlight.y = heartHighlight.y - 95;
                        heartHighlight.fps = 30;
                        this._lilReelsView._heartBeatAnims[i].addChild(heartHighlight);
                        heartHighlight.addEventListener(rendering.DisplayEvent.ANIMATION_COMPLETE, this.onAllHeartAnimComplete1, this);
                        heartHighlight.gotoAndPlay(0);
                    }
                }
                else {
                    var reelId = 0;
                    if (reelSpinData.lilSpinData.numTotalLilSpins == reelSpinData.lilSpinData.remainingLilSpins) {
                        this._heartGrpCnr = 0;
                        this.timerToken = setInterval(function () {
                            while (reelSpinData.heartAwardMultipliers[reelId] == 0 && reelId < 15) {
                                reelId++;
                            }
                            _this.updateMonetaryValues(reelId++);
                            if (reelId > 14 && reelSpinData.lilSpinData.lastLILSpin == false) {
                                clearInterval(_this.timerToken);
                                if (!_this._forceModel.forceOpen) {
                                    TweenMax.delayedCall(1, function () {
                                        if (!_this._forceModel.forceOpen) {
                                            _this._statesModel.changeStateByName(sgigame.BonusGameState.LIL_SPIN);
                                        }
                                    }, [], _this);
                                }
                            }
                            else if (reelId > 15 && reelSpinData.lilSpinData.lastLILSpin == true) {
                                clearInterval(_this.timerToken);
                                _this.addAwardsInTally();
                            }
                        }, 300);
                    }
                    else if (reelSpinData.lilSpinData.lastLILSpin == false && !this._forceModel.forceOpen) {
                        this._statesModel.changeStateByName(sgigame.BonusGameState.LIL_SPIN);
                    }
                    else if (reelSpinData.lilSpinData.lastLILSpin == true) {
                        this.addAwardsInTally();
                    }
                }
            }
        }

